#[repr(C)]
#[derive(Debug, Copy, Clone)]
pub struct tagVersionedStream {
    pub guidVersion: GUID,
    pub pStream: *mut IStream,
}
#[test]
fn bindgen_test_layout_tagVersionedStream() {
    const UNINIT: ::std::mem::MaybeUninit<tagVersionedStream> = ::std::mem::MaybeUninit::uninit();
    let ptr = UNINIT.as_ptr();
    assert_eq!(
        ::std::mem::size_of::<tagVersionedStream>(),
        24usize,
        concat!("Size of: ", stringify!(tagVersionedStream))
    );
    assert_eq!(
        ::std::mem::align_of::<tagVersionedStream>(),
        8usize,
        concat!("Alignment of ", stringify!(tagVersionedStream))
    );
    assert_eq!(
        unsafe { ::std::ptr::addr_of!((*ptr).guidVersion) as usize - ptr as usize },
        0usize,
        concat!("Offset of field: ", stringify!(tagVersionedStream), "::", stringify!(guidVersion))
    );
    assert_eq!(
        unsafe { ::std::ptr::addr_of!((*ptr).pStream) as usize - ptr as usize },
        16usize,
        concat!("Offset of field: ", stringify!(tagVersionedStream), "::", stringify!(pStream))
    );
}
pub type VERSIONEDSTREAM = tagVersionedStream;
pub type LPVERSIONEDSTREAM = *mut tagVersionedStream;
