pub struct tagSERIALIZEDPROPERTYVALUE {
    pub dwType: DWORD,
    pub rgb: [BYTE; 1usize],
}
#[test]
fn bindgen_test_layout_tagSERIALIZEDPROPERTYVALUE() {
    const UNINIT: ::std::mem::MaybeUninit<tagSERIALIZEDPROPERTYVALUE> =
        ::std::mem::MaybeUninit::uninit();
    let ptr = UNINIT.as_ptr();
    assert_eq!(
        ::std::mem::size_of::<tagSERIALIZEDPROPERTYVALUE>(),
        8usize,
        concat!("Size of: ", stringify!(tagSERIALIZEDPROPERTYVALUE))
    );
    assert_eq!(
        ::std::mem::align_of::<tagSERIALIZEDPROPERTYVALUE>(),
        4usize,
        concat!("Alignment of ", stringify!(tagSERIALIZEDPROPERTYVALUE))
    );
    assert_eq!(
        unsafe { ::std::ptr::addr_of!((*ptr).dwType) as usize - ptr as usize },
        0usize,
        concat!(
            "Offset of field: ",
            stringify!(tagSERIALIZEDPROPERTYVALUE),
            "::",
            stringify!(dwType)
        )
    );
    assert_eq!(
        unsafe { ::std::ptr::addr_of!((*ptr).rgb) as usize - ptr as usize },
        4usize,
        concat!("Offset of field: ", stringify!(tagSERIALIZEDPROPERTYVALUE), "::", stringify!(rgb))
    );
}
