#[repr(C)]
#[derive(Debug, Copy, Clone)]
pub struct NUMPARSE {
    pub cDig: INT,
    pub dwInFlags: ULONG,
    pub dwOutFlags: ULONG,
    pub cchUsed: INT,
    pub nBaseShift: INT,
    pub nPwr10: INT,
}
#[test]
fn bindgen_test_layout_NUMPARSE() {
    const UNINIT: ::std::mem::MaybeUninit<NUMPARSE> = ::std::mem::MaybeUninit::uninit();
    let ptr = UNINIT.as_ptr();
    assert_eq!(
        ::std::mem::size_of::<NUMPARSE>(),
        24usize,
        concat!("Size of: ", stringify!(NUMPARSE))
    );
    assert_eq!(
        ::std::mem::align_of::<NUMPARSE>(),
        4usize,
        concat!("Alignment of ", stringify!(NUMPARSE))
    );
    assert_eq!(
        unsafe { ::std::ptr::addr_of!((*ptr).cDig) as usize - ptr as usize },
        0usize,
        concat!("Offset of field: ", stringify!(NUMPARSE), "::", stringify!(cDig))
    );
    assert_eq!(
        unsafe { ::std::ptr::addr_of!((*ptr).dwInFlags) as usize - ptr as usize },
        4usize,
        concat!("Offset of field: ", stringify!(NUMPARSE), "::", stringify!(dwInFlags))
    );
    assert_eq!(
        unsafe { ::std::ptr::addr_of!((*ptr).dwOutFlags) as usize - ptr as usize },
        8usize,
        concat!("Offset of field: ", stringify!(NUMPARSE), "::", stringify!(dwOutFlags))
    );
    assert_eq!(
        unsafe { ::std::ptr::addr_of!((*ptr).cchUsed) as usize - ptr as usize },
        12usize,
        concat!("Offset of field: ", stringify!(NUMPARSE), "::", stringify!(cchUsed))
    );
    assert_eq!(
        unsafe { ::std::ptr::addr_of!((*ptr).nBaseShift) as usize - ptr as usize },
        16usize,
        concat!("Offset of field: ", stringify!(NUMPARSE), "::", stringify!(nBaseShift))
    );
    assert_eq!(
        unsafe { ::std::ptr::addr_of!((*ptr).nPwr10) as usize - ptr as usize },
        20usize,
        concat!("Offset of field: ", stringify!(NUMPARSE), "::", stringify!(nPwr10))
    );
}
